from typing import List
def total_cost(bits_per_step: List[int], tf: float) -> float:
    return sum(bits_per_step) * tf

import math
def max_admissible_steps(budget: float, tf: float) -> int:
    if tf <= 0:
        raise ValueError('tempFactor must be positive')
    return math.floor(budget / tf)

import math
def brute_force_floor(key_bits: int, kB: float = 1.380649e-23, T: float = 300.0) -> float:
    return (2 ** key_bits) * kB * T * math.log(2.0)

