import math
K_B = 1.380649e-23  # J/K
def temp_factor(T: float = 300.0) -> float:
    return K_B * T * math.log(2.0)
tf = temp_factor(300.0)
print(f'tf = {tf:.6e} J/bit, positive? {tf > 0}')
